@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800&family=IBM+Plex+Mono:wght@400;500;600&display=swap');
:root{--bg:#070b11;--panel:#0b1119;--line:#1d2933;--muted:#75838b;--text:#dce4df;--acid:#c6f36a;--red:#e75f55;--cyan:#68d5d0;--mono:'IBM Plex Mono',monospace;--display:'Barlow Condensed',sans-serif}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#05080d;color:var(--text);font-family:var(--mono)}body{padding:0 22px;background:radial-gradient(ellipse at 50% 30%,#121a22 0,#080c12 50%,#05070b 100%);min-height:100vh}.game-shell{max-width:1512px;margin:0 auto;min-height:100vh;display:flex;flex-direction:column}.topbar{height:62px;border-bottom:1px solid #1c252c;display:flex;align-items:center;justify-content:space-between;flex:none}.brand{display:flex;align-items:center;gap:10px;color:#e5ece5;text-decoration:none;font:800 18px var(--display);letter-spacing:1.5px}.brand-mark{width:26px;height:26px;display:grid;place-items:center;background:var(--acid);color:#101710;font:700 11px var(--mono);letter-spacing:-1px;clip-path:polygon(0 0,100% 0,100% 74%,73% 100%,0 100%)}.brand-dim{color:#718078}.top-status{font-size:10px;letter-spacing:1.1px;color:#89958f;display:flex;align-items:center;gap:10px}.live-dot,.warning-tag i{width:6px;height:6px;border-radius:50%;background:#c9f475;box-shadow:0 0 9px #b4e861}.signal{color:#c0e76a;letter-spacing:-3px;margin-left:8px}.sound-toggle{border:1px solid #2a353d;background:none;color:#b1beb4;padding:8px 11px;font:10px var(--mono);letter-spacing:.8px;cursor:pointer}.sound-toggle:hover{border-color:var(--acid);color:var(--acid)}.sound-toggle span{margin-left:5px}.game-layout{display:grid;grid-template-columns:220px minmax(400px,1fr) 220px;gap:18px;padding:20px 0 14px;flex:1;align-items:start}.side-panel{font-size:10px}.eyebrow,.card-label{font-size:9px;color:#7e8d92;letter-spacing:1.25px;font-weight:600;display:flex;justify-content:space-between}.eyebrow{margin:3px 0 12px}.eyebrow span,.card-label span{color:#52636b}.ship-card,.inventory-card,.objective-card,.floor-mini,.signal-card,.crew-card,.log-card{border:1px solid var(--line);background:linear-gradient(145deg,#0d151c,#091017);margin-bottom:12px;padding:13px}.card-label{margin-bottom:13px}.host-row{display:flex;align-items:center;gap:11px;margin:3px 0 13px}.host-icon{width:38px;height:38px;display:grid;place-items:center;border:1px solid #576d43;color:var(--acid);font-size:22px;background:radial-gradient(circle,#253124,#0c1312)}.host-row h2{margin:0;color:#e5f1d8;font:700 20px var(--display);letter-spacing:1.4px}.host-row p{margin:1px 0;color:#829187;font-size:8px;letter-spacing:.6px}.meter-label{display:flex;justify-content:space-between;color:#809089;font-size:8px;letter-spacing:.6px;margin:9px 0 5px}.meter-label b{color:#d8e6d2;font-weight:500}.meter{height:5px;background:#1a2526;overflow:hidden}.meter i{height:100%;display:block;width:100%;background:#b4e766;box-shadow:0 0 8px #95d34b;transition:width .2s}.energy-label{margin-top:11px}.energy-meter i{background:#5fcac2;box-shadow:0 0 8px #4ba9a5}.host-note{font-size:9px;color:#77837f;line-height:1.6;margin:11px 0 0;min-height:28px}.inventory-card{padding-bottom:8px}.inventory-row{display:flex;align-items:center;gap:9px;padding:7px 0;border-top:1px solid #17212a;color:#aab5af;font-size:8px;letter-spacing:.45px}.inventory-row b{margin-left:auto;color:#e0e8d9;font-weight:500;font-size:9px}.inv-icon{font-size:14px;width:16px;text-align:center}.key-icon{color:#d4be6c}.med-icon{color:#e97564}.ammo-icon{color:#64c8c3}.objective-card{display:flex;align-items:center;gap:10px;position:relative;padding-top:30px}.objective-card>.card-label{position:absolute;top:12px;left:13px}.objective-icon{font-size:22px;color:var(--acid)}.objective-card strong{font:600 13px var(--display);letter-spacing:.8px;color:#d9e8ca}.objective-card p{color:#82908b;font-size:8px;line-height:1.6;margin:3px 0 0}.floor-mini{padding-bottom:10px}.minimap{height:88px;background-color:#080e12;background-image:linear-gradient(#142128 1px,transparent 1px),linear-gradient(90deg,#142128 1px,transparent 1px);background-size:12px 12px;position:relative;overflow:hidden;border:1px solid #1b2b30}.mini-wall{position:absolute;background:#344348}.mini-point{position:absolute;width:4px;height:4px;border-radius:50%;background:#ef6c59;box-shadow:0 0 5px #ef6c59}.mini-player{position:absolute;width:5px;height:5px;border-radius:50%;background:var(--acid);box-shadow:0 0 8px var(--acid);z-index:2}.mini-goal{position:absolute;width:5px;height:5px;border:1px solid #72d5d1;z-index:1}.map-legend{font-size:7px;color:#7b8985;display:flex;align-items:center;gap:5px;margin-top:8px}.map-legend i{width:5px;height:5px;border-radius:50%;display:inline-block;margin-left:3px}.legend-you{background:var(--acid)}.legend-hostile{background:#ef6c59}.legend-goal{border:1px solid #72d5d1}.play-area{min-width:0}.game-topline{display:flex;justify-content:space-between;align-items:end;margin:0 1px 10px}.game-topline .eyebrow{margin:0 0 2px;font-size:8px}.game-topline h1{font:700 26px/.95 var(--display);letter-spacing:1.5px;color:#e4e9e3;margin:0}.game-topline h1 span{font:500 14px var(--mono);color:#768277;margin-left:6px}.mission-clock{text-align:right}.mission-clock span{display:block;color:#718079;font-size:8px;letter-spacing:1px}.mission-clock b{display:block;color:#d5e0d1;font-size:16px;font-weight:500;margin-top:3px;letter-spacing:1px}.canvas-frame{position:relative;overflow:hidden;border:1px solid #34413f;background:#070c10;box-shadow:0 0 0 4px #0a1015,0 16px 42px #0008;aspect-ratio:896/576;max-height:calc(100vh - 230px);min-height:350px}.canvas-frame canvas{display:block;width:100%;height:100%;object-fit:contain;image-rendering:pixelated}.scanlines,.vignette{position:absolute;inset:0;pointer-events:none;z-index:2}.scanlines{opacity:.12;background:repeating-linear-gradient(0deg,transparent 0 2px,#000 3px 4px);mix-blend-mode:multiply}.vignette{background:radial-gradient(ellipse at center,transparent 45%,#020508a8 100%)}.toast{position:absolute;z-index:4;top:14px;left:50%;transform:translate(-50%,-10px);background:#101b1bde;border:1px solid #4d7061;color:#d8edc7;padding:8px 14px;font-size:9px;letter-spacing:.6px;opacity:0;transition:.3s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.game-overlay{position:absolute;inset:0;z-index:5;display:grid;place-items:center;background:radial-gradient(ellipse at 50% 45%,#0a1116a8,#05080ee8 70%);}.hidden{display:none!important}.overlay-content{text-align:center;width:min(90%,560px)}.warning-tag{display:inline-flex;align-items:center;gap:8px;padding:6px 10px;border:1px solid #3e5746;color:#b7cd9b;font-size:8px;letter-spacing:1.4px}.warning-tag i{width:5px;height:5px}.intro-content h2,.end-content h2{font:800 clamp(52px,8vw,82px)/.76 var(--display);letter-spacing:5px;margin:20px 0 16px;color:#eef3e7;text-shadow:0 2px 24px #a5e76623}.intro-content h2 span,.end-content h2 span{color:var(--acid)}.intro-sub{font:600 13px var(--display);letter-spacing:3px;color:#8da397;margin:0}.intro-rule{width:34px;height:1px;background:#637d58;margin:17px auto}.intro-copy{font-size:10px;line-height:1.8;color:#a2ada4;margin:0 auto 20px}.primary-btn{border:0;background:var(--acid);color:#11190c;padding:12px 20px;font:700 12px var(--mono);letter-spacing:1px;cursor:pointer;box-shadow:0 0 22px #a8e55a2b;transition:.2s}.primary-btn span{font-size:15px;margin-left:16px}.primary-btn:hover{background:#e2ff9f;transform:translateY(-2px);box-shadow:0 5px 25px #a8e55a59}.control-hint{margin:19px auto 0;color:#718078;font-size:7px;letter-spacing:.35px}.control-hint b{color:#c5dc86;font-weight:400}.game-bottomline{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #202a30;padding:11px 2px}.status-message{display:flex;align-items:center;gap:8px;color:#829188;font-size:9px}.status-icon{color:var(--acid);font-size:12px}.floor-progress{display:flex;align-items:center;gap:9px;color:#79877c;font-size:8px;letter-spacing:.8px}.progress-dots{display:flex;gap:4px}.progress-dots i{width:18px;height:3px;background:#25312e}.progress-dots i.active{background:var(--acid);box-shadow:0 0 5px #b5eb62}.signal-card{padding:13px}.signal-head{display:flex;justify-content:space-between;font-size:8px;color:#a3afa5;letter-spacing:.7px}.signal-head b{font-weight:500;color:#e67562}.pressure-bars{display:flex;gap:2px;margin:9px 0 8px;height:14px;align-items:end}.pressure-bars i{display:block;flex:1;height:100%;background:#34413b}.pressure-bars i:nth-child(1){height:36%}.pressure-bars i:nth-child(2){height:53%}.pressure-bars i:nth-child(3){height:65%}.pressure-bars i:nth-child(4){height:80%}.pressure-bars i:nth-child(5){height:92%}.pressure-bars i:nth-child(-n+5){background:#a44c43}.pressure-readout{font-size:16px;color:#e2e8dd;font-weight:500}.pressure-readout small{font-size:9px;color:#7b8982}.pressure-readout span{display:block;font-size:7px;letter-spacing:.3px;color:#738178;margin-top:4px}.crew-card{padding-bottom:3px}.crew-person{display:flex;align-items:center;gap:8px;padding:8px 0;border-top:1px solid #17212a}.crew-avatar{width:23px;height:23px;border:1px solid #35443e;display:grid;place-items:center;font-size:13px;color:#8ca191}.avatar-1{color:#dc7767}.avatar-2{color:#b4cd75}.avatar-3{color:#67d2c7}.avatar-4{color:#947caa}.crew-person div{min-width:0}.crew-person b{display:block;font-size:8px;letter-spacing:.4px;color:#cad3ca;font-weight:500}.crew-person small{display:block;font-size:7px;color:#718078;margin-top:3px;white-space:nowrap}.crew-state{margin-left:auto;font-size:7px;letter-spacing:.5px}.crew-state.lost{color:#c36558}.crew-state.unknown{color:#d1b764}.crew-state.active{color:#94d56b}.log-card{padding-bottom:8px}.log-card .card-label span{color:#b2d16d}.log-lines{border-left:1px solid #36443b;padding-left:9px}.log-lines p{margin:7px 0;color:#849087;font-size:8px;line-height:1.5}.log-lines time{color:#65756d}.log-lines p span{color:#c3d67b}.warning-card{display:flex;gap:10px;align-items:center;background:#201513;border:1px solid #49302a;padding:10px}.warning-card>span{font:700 18px var(--display);color:#e97460}.warning-card p{font-size:8px;line-height:1.6;color:#9e8980;margin:0}.warning-card b{font-weight:600;color:#d77d67;letter-spacing:.5px}.hack-panel{text-align:center;width:min(90%,450px);padding:24px;background:#081015ef;border:1px solid #4b7869;box-shadow:0 0 55px #57d2bb22}.hack-panel h2{font:800 38px/.86 var(--display);letter-spacing:3px;margin:14px 0;color:#e7f2e7}.hack-panel h2 span{color:var(--cyan)}.hack-panel>p{font-size:9px;color:#9caca4;line-height:1.6}.pulse-sequence{display:flex;justify-content:center;gap:8px;margin:18px 0}.pulse-sequence i{width:32px;height:32px;border:1px solid #34433e;display:grid;place-items:center;color:#71837c;font-style:normal;font-size:15px}.pulse-sequence i.active{border-color:#bde876;color:#d5fa8e;background:#28361d;box-shadow:0 0 14px #b8e76944}.pulse-sequence i.done{border-color:#5ac7bd;color:#5ac7bd}.hack-inputs{display:flex;justify-content:center;gap:8px}.hack-inputs button{width:43px;height:38px;border:1px solid #34433e;background:#111b20;color:#d2e6d5;font:16px var(--mono);cursor:pointer}.hack-inputs button:hover{border-color:var(--cyan);color:var(--cyan)}.hack-panel .hack-foot{font-size:7px;letter-spacing:.5px;color:#73837b;margin:14px 0 0}.hack-foot b{color:var(--cyan)}.end-content h2{font-size:clamp(44px,7vw,72px)}.touch-controls{display:none}footer{height:35px;border-top:1px solid #1b242b;display:flex;justify-content:space-between;align-items:center;color:#58665f;font-size:7px;letter-spacing:.8px;flex:none}footer b{color:#a0b85f;font-weight:400}.shake{animation:shake .22s linear}@keyframes shake{25%{transform:translateX(-4px)}50%{transform:translateX(4px)}75%{transform:translateX(-2px)}}
@media(max-width:1100px){body{padding:0 14px}.game-layout{grid-template-columns:190px minmax(360px,1fr) 190px;gap:12px}.side-panel{font-size:9px}.ship-card,.inventory-card,.objective-card,.floor-mini,.signal-card,.crew-card,.log-card{padding:10px}.game-topline h1{font-size:22px}}
@media(max-width:850px){body{padding:0 10px}.game-layout{grid-template-columns:1fr;padding-top:12px}.left-panel,.right-panel{display:none}.play-area{width:100%}.canvas-frame{min-height:0;max-height:none}.topbar{height:49px}.top-status{font-size:8px}.game-topline{margin-bottom:7px}.game-topline h1{font-size:20px}.game-bottomline{padding:8px 2px}.touch-controls{display:flex;justify-content:space-between;align-items:center;padding:11px 16px 6px;max-width:530px;margin:auto;width:100%;touch-action:none}.dpad>button,.dpad div button,.touch-actions button{background:#111b20;border:1px solid #314039;color:#b9d1a2;touch-action:none}.dpad>button{display:block;width:39px;height:30px;margin:0 auto 3px}.dpad div{display:flex;gap:3px}.dpad div button{width:39px;height:30px}.touch-actions{display:flex;gap:10px}.touch-actions button{width:53px;height:53px;border-radius:50%;font:16px var(--mono);color:var(--acid);border-color:#627c4f}.touch-actions button small{font:7px var(--mono);letter-spacing:.5px;color:#93a38e}.touch-actions button:active,.dpad button:active{background:#31432d}footer{font-size:6px}.canvas-frame{aspect-ratio:896/576}.control-hint{font-size:6px}.intro-content h2{font-size:60px}}
@media(max-width:480px){body{padding:0 7px}.top-status{letter-spacing:.3px;gap:5px}.signal{display:none}.sound-toggle{padding:6px;font-size:8px}.sound-toggle span{font-size:7px}.game-topline h1{font-size:18px}.game-topline .eyebrow{font-size:7px}.mission-clock b{font-size:12px}.game-bottomline{font-size:7px}.status-message{font-size:7px}.floor-progress{gap:5px;font-size:7px}.progress-dots i{width:11px}.intro-content h2{font-size:48px;letter-spacing:3px}.intro-sub{font-size:10px}.intro-copy{font-size:8px}.control-hint{max-width:270px;line-height:1.8}.primary-btn{font-size:10px;padding:10px 14px}.touch-controls{padding:7px 12px 2px}.dpad>button,.dpad div button{width:33px;height:27px}.touch-actions button{width:46px;height:46px}footer span:nth-child(2){display:none}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height, T = 32, COLS = 28, ROWS = 18;
  const $ = id => document.getElementById(id);
  const keysDown = new Set();
  const pointer = { x: W / 2, y: H / 2, down: false, seen: false };
  const arrows = ['←','↑','↓','→'];
  const dirs = [[-1,0],[0,-1],[0,1],[1,0]];
  const floors = [
    {name:'CARGO DECK', subtitle:'MANIFEST: 87 / 87', keys:[[5,3],[22,7],[9,14]], spawn:[2,2], goal:[26,16], enemies:[[8,2,'stalker'],[16,5,'security'],[23,12,'stalker'],[5,10,'worker']]},
    {name:'MEDICAL WING', subtitle:'LIFE SUPPORT: OFFLINE', keys:[[4,13],[18,3],[23,14]], spawn:[2,2], goal:[26,16], enemies:[[8,3,'medic'],[18,9,'security'],[7,14,'stalker'],[23,5,'medic']]},
    {name:'REACTOR / BRIDGE', subtitle:'CORE TEMP: 1,422°C', keys:[[5,13],[21,3],[10,9]], spawn:[2,2], goal:[26,16], enemies:[[7,3,'security'],[18,6,'stalker'],[7,14,'worker']], boss:[23,8]}
  ];
  const hostTypes = {
    wraith:{name:'WRAITH',type:'DISCORPOREAL ENTITY',icon:'◈',note:'Phase through hostile signals. No weapon — stay unseen.',speed:148,energy:100,drain:0,damage:0,color:'#c9f475',weapon:false},
    worker:{name:'DECKHAND-04',type:'INDUSTRIAL AUTOMATON',icon:'▣',note:'Slow and durable. A heavy rivet driver stuns at close range.',speed:125,energy:100,drain:1.75,damage:27,color:'#edb655',weapon:true},
    security:{name:'SENTRY K-17',type:'SECURITY SYNTH',icon:'⊕',note:'Fast target lock. Pulse rifle hits hard, but drains quickly.',speed:160,energy:100,drain:3.3,damage:20,color:'#62d2c7',weapon:true},
    stalker:{name:'STALKER',type:'XENOMORPH / CLASS UNKNOWN',icon:'⌁',note:'Fast, vicious, and built for the dark. Claws tear through armor.',speed:176,energy:100,drain:2.5,damage:32,color:'#d679c7',weapon:true},
    medic:{name:'MED-TECH 9',type:'AUTONOMOUS MEDICAL UNIT',icon:'✚',note:'A steady host with a restorative pulse. Short-range defense only.',speed:138,energy:100,drain:2.1,damage:15,color:'#88d783',weapon:true}
  };
  let game = {started:false,over:false,won:false,floor:0,grid:[],player:null,enemies:[],bullets:[],items:[],keys:0,medkits:1,health:100,elapsed:0,last:0,shots:0,noise:0,goal:null,boss:null,hack:null,host:'wraith',hostEnergy:100,invuln:0,toastTimer:0,spawnTimer:0};
  let audioCtx = null, musicTimer = null, soundOn = true, lastTone = 0;

  function makeMap(){
    const g=Array.from({length:ROWS},()=>Array(COLS).fill(0));
    for(let y=0;y<ROWS;y++) for(let x=0;x<COLS;x++) if(x===0||y===0||x===COLS-1||y===ROWS-1)g[y][x]=1;
    // Broken bulkheads create connected, maze-like rooms. The gaps are intentional routes.
    const horizontal=[{y:4,gaps:[4,13,22]},{y:8,gaps:[8,17,25]},{y:12,gaps:[3,12,21]},{y:15,gaps:[7,18,24]}];
    horizontal.forEach(({y,gaps})=>{for(let x=1;x<COLS-1;x++)if(!gaps.includes(x))g[y][x]=1;});
    const vertical=[{x:7,gaps:[2,6,10,14]},{x:14,gaps:[3,7,11,15]},{x:21,gaps:[2,5,9,13,16]}];
    vertical.forEach(({x,gaps})=>{for(let y=1;y<ROWS-1;y++)if(!gaps.includes(y)&&![4,8,12,15].includes(y))g[y][x]=1;});
    // Short partitions and dead-end alcoves add navigational texture.
    [[3,6,2],[4,10,3],[10,2,2],[10,6,2],[11,9,2],[18,2,2],[18,10,2],[24,10,2],[3,15,2],[14,13,2],[23,15,2]].forEach(([x,y,len])=>{for(let i=0;i<len;i++)if(g[y][x+i]===0)g[y][x+i]=1;});
    // Doorways / open up all authored item and spawn cells.
    const f=floors[game.floor]; [f.spawn,f.goal,...f.keys,...f.enemies.map(e=>e.slice(0,2)),f.boss].filter(Boolean).forEach(([x,y])=>{g[y][x]=0;if(g[y][x+1]===1)g[y][x+1]=0;});
    return g;
  }
  function center(tx,ty){return {x:tx*T+T/2,y:ty*T+T/2}}
  function setupFloor(index){
    game.floor=index; const f=floors[index];game.grid=makeMap();game.player={...center(...f.spawn),vx:0,vy:0,faceX:1,faceY:0,r:9};game.goal={...center(...f.goal)};
    game.enemies=f.enemies.map(([x,y,type],i)=>({x:x*T+16,y:y*T+16,type,hp:type==='security'?70:type==='stalker'?55:65,maxHp:type==='security'?70:type==='stalker'?55:65,r:type==='stalker'?10:11,angle:Math.random()*6.28,alert:false,shot:1+Math.random()*2,hit:0,id:`${index}-${i}`}));
    game.boss=f.boss?{...center(...f.boss),hp:380,maxHp:380,r:23,angle:0,shot:1.5,hit:0}:null;
    game.items=f.keys.map(([x,y],i)=>({x:x*T+16,y:y*T+16,type:'key',taken:false,id:i}));
    const meds=index===0?[[12,10]]:index===1?[[12,5],[4,9]]:[[18,13]];
    meds.forEach(([x,y])=>game.items.push({x:x*T+16,y:y*T+16,type:'med',taken:false}));
    const batteries=index===0?[[18,14],[3,7]]:[[4,5],[20,12]]; batteries.forEach(([x,y])=>game.items.push({x:x*T+16,y:y*T+16,type:'battery',taken:false}));
    updateMap(); updateFloorUI();
  }
  function updateFloorUI(){
    $('floorName').innerHTML=`${floors[game.floor].name} <span>0${game.floor+1}</span>`;$('mapFloor').textContent=`0${game.floor+1}`;$('deckCounter').textContent=`0${game.floor+1} / 03`;
    document.querySelectorAll('.progress-dots i').forEach((el,i)=>el.classList.toggle('active',i<=game.floor));
    $('objectiveTitle').textContent=game.floor===2?'DESTROY THE CORE':'FIND 3 ACCESS KEYS';$('objectiveText').textContent=game.floor===2?'Break the core. The lift won't save you.':'Search the deck. Reach the sealed lift.';
    updateMap();
  }
  function updateMap(){
    const el=$('minimap');el.innerHTML='';const scaleX=el.clientWidth/W,scaleY=el.clientHeight/H;
    for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++)if(game.grid[y]?.[x]){const n=document.createElement('i');n.className='mini-wall';n.style.cssText=`left:${x*T*scaleX}px;top:${y*T*scaleY}px;width:${T*scaleX}px;height:${T*scaleY}px`;el.appendChild(n)}
    const add=(cls,x,y)=>{const n=document.createElement('i');n.className=cls;n.style.cssText=`left:${x*scaleX-2}px;top:${y*scaleY-2}px`;el.appendChild(n)};
    game.items?.filter(a=>!a.taken&&a.type==='key').forEach(a=>add('mini-goal',a.x,a.y));game.enemies?.forEach(a=>add('mini-point',a.x,a.y));if(game.boss)add('mini-point',game.boss.x,game.boss.y);if(game.goal)add('mini-goal',game.goal.x,game.goal.y);if(game.player)add('mini-player',game.player.x,game.player.y);
  }
  function updateUI(){
