(async () => {
  const targets = await fetch('http://127.0.0.1:9223/json').then(r => r.json());
  const page = targets.find(t => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let id = 0;
  const pending = new Map();
  ws.onmessage = event => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      pending.get(message.id)(message);
      pending.delete(message.id);
    }
  };
  const evaluate = expression => new Promise(resolve => {
    const callId = ++id;
    pending.set(callId, message => resolve(message.result?.result?.value ?? message.result?.exceptionDetails?.text));
    ws.send(JSON.stringify({id: callId, method: 'Runtime.evaluate', params: {expression, awaitPromise: true, returnByValue: true}}));
  });
  const result = await evaluate(`(async()=>{
    document.getElementById('startButton').click();
    await new Promise(r=>setTimeout(r,150));
    const g=window.__gameDebug, report=[];
    g.enemies=[];
    for(let floor=0;floor<2;floor++){
      for(const item of g.items.filter(a=>a.type==='key')){
        g.player.x=item.x;g.player.y=item.y;
        await new Promise(r=>setTimeout(r,100));
      }
      report.push({deck:floor+1,keys:g.keys});
      g.player.x=g.goal.x;g.player.y=g.goal.y;
